  | { t: "b" | "i"; c: Inline[] }
  | { t: "code"; v: string }
  | { t: "a"; href: string; c: Inline[] };

export type Block =
  | { t: "p"; lines: string[] }
  | { t: "ul" | "ol"; items: string[] };

const UL = /^\s{0,3}[-*+]\s+(.*)$/;
const OL = /^\s{0,3}\d{1,9}[.)]\s+(.*)$/;

export function parseBlocks(text: string): Block[] {
  const out: Block[] = [];
